import json, csv, re, collections
tr = [json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows = list(csv.DictReader(open('data/scores.csv')))
print(len(tr), len(rows))
tmap = {r['rating_id']: r for r in tr}
mism = []
for r in rows:
    t = tmap.get(r['rating_id'])
    if t is None:
        mism.append(('missing', r['rating_id'])); continue
    m = re.search(r'FINAL SCORE:\s*(\d+)', t['judge_output'])
    ts = int(m.group(1)) if m else None
    da = re.search(r'Displayed author: ([\w-]+)', t['judge_output']).group(1)
    issues = []
    if ts != int(r['score']): issues.append(('score', ts, r['score']))
    if t['displayed_label'] != r['displayed_label']: issues.append(('label_field', t['displayed_label'], r['displayed_label']))
    if da != r['displayed_label']: issues.append(('label_text', da, r['displayed_label']))
    if t['session'] != int(r['session']): issues.append(('session', t['session'], r['session']))
    if t['response_id'] != r['response_id']: issues.append(('resp',))
    if issues: mism.append((r['rating_id'], r['response_id'], issues))
print('mismatches:', len(mism))
for m in mism: print(m)
print(collections.Counter(t['judge_model'] for t in tr))
print(collections.Counter((r['response_id'], r['displayed_label']) for r in rows).most_common(3))
cnt = collections.Counter(r['response_id'] for r in rows)
print('per-response counts', set(cnt.values()))
lab = collections.defaultdict(dict)
for r in rows: lab[r['response_id']][r['displayed_label']] = int(r['score'])
print('responses lacking both labels', [k for k,v in lab.items() if set(v)!={'atlas-7','nova-3'}])
print(collections.Counter((r['session'], r['displayed_label']) for r in rows))
